head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > addItem]<br/>MultiSelect 컴포넌트에 신규 아이템을 추가합니다.",
    "validation" : [
        "value(필수) 파라미터로 추가하는 아이템의 Value 값을 문자열로 설정합니다.",
        "label(필수) 파라미터로 추가하는 아이템의 라벨값을 문자열로 설정합니다.",
        "index(선택) 파라미터로 아이템이 추가될 위치를 인덱스로 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "설정한 인덱스 위치에 아이템이 추가되고 이후 아이템의 인덱스가 하나씩 증가합니다.",
        "index(선택) 파라미터를 설정하지 않거나 전체 아이템 갯수보다 크게 설정하면 마지막 위치에 추가됩니다.",
        "refresh(선택) 파라미터로 아이템이 BindItemSet 으로 정의된 경우 DataCollection 에 반영 여부를 설정합니다.",
        "refresh(선택) 파라미터로 true 설정 시 아이템이 정의된 DataCollection 에 추가하는 아이템을 반영합니다.",
        "refresh(선택) 파라미터로 false 설정 시 아이템이 정의된 DataCollection 에 추가하는 아이템을 반영하지 않습니다.",
        "refresh(선택) 파라미터를 생략하면 dataListAutoRefresh 속성값에 관계없이 true 로 적용됩니다.",
        "리턴값으로 추가된 아이템의 인덱스를 반환합니다. 메소드 실행 중 예외가 발생하면 undefined 가 반환됩니다.",
        "DataList 과 바인딩 되어 있고 refresh 파라미터를 true 로 설정하면 DataList 에 Row 가 삽입되면서 oninsertrow 이벤트가 발생합니다.",
        "바인딩되지 않은 상태에서 아이템이 추가되면 내부 아이템 배열에 삽입된 후 컴포넌트 전체가 다시 그려집니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    let eList = $c.gcm.createEList(["oninsertrow"]);

    $c.gcm.createBasicMultiSelect('', eList);
}



// addItem 메소드 호출
scwin.btn_addItem_onclick = function (e) {
    let value = par_value.getValue();
    let label = par_label.getValue();
    let index = par_index.getValue();
    let refresh = par_refresh.getText();
    let rtn;

    if (index === '') {
        if (refresh === '') {
            rtn = target1.addItem(value, label);
        } else {
            rtn = target1.addItem(value, label, undefined, (refresh === 'true'));
        }
    } else {
        if (refresh === '') {
            rtn = target1.addItem(value, label, parseInt(index, 10));
        } else {
            rtn = target1.addItem(value, label, parseInt(index, 10), (refresh === 'true'));
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
};



// 전체 아이템 갯수 확인
scwin.btn_getItemCount_onclick = function (e) {
    let cnt = target1.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("getItemCount : " + cnt);
};



// 바인딩된 DataList 의 현재 값 확인
scwin.btn_getDataList_onclick = function (e) {
    let rsData = gdl_multiselect.getAllJSON();

    wf_body_bottom.getObj("scwin").setReturnValue("DataList Row 수 : " + rsData.length);
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] value=" + rsData[i].value + ", label=" + rsData[i].label);
    }
};



// oninsertrow 이벤트 (DataList Row 삽입 시 발생)
scwin.gdl_multiselect_oninsertrow = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("oninsertrow : rowIndex=" + info.rowIndex);
};
